/**
 * Filters the picker. The list is too long to scan, and the person searching
 * it is often the one who cannot read the current language at all — having
 * tapped the wrong row, or picked up a phone set to someone else's. So the
 * English name and the code match too, not just the language's own name: a
 * reader stranded in Armenian can still find their way out by typing "eng".
 */
export const languageMatches = (
  lang: {code: string; label: string; nativeLabel: string},
  query: string,
): boolean => {
  const q = query.trim().toLowerCase();
  if (!q) return true;
  return [lang.label, lang.nativeLabel, lang.code].some(v => v.toLowerCase().includes(q));
};

/**
 * Right-to-left scripts. Sets `dir` on the document so paragraphs, inputs and
 * native text flow read correctly; this does not mirror the app's own flex
 * layouts (message alignment, icon placement), which is a separate, larger
 * pass — see mobile's src/i18n/rtl.ts for the equivalent it does have, via
 * React Native's layout-level RTL flip, which has no web equivalent.
 */
const RTL_LANGUAGES: readonly Lang[] = ['ar', 'fa', 'he', 'ur'];

