interface I18nCtx {
  lang: Lang;
  setLang: (l: Lang) => void;
  /**
   * `t('newChat.full', {max: 32})` fills `{max}` in the string. A placeholder
   * with no matching variable is left as written rather than blanked, so a
   * translation that kept a slot the caller stopped passing shows the slot
   * instead of a hole.
   */
  t: (key: Key, vars?: Record<string, string | number>) => string;
}

const Ctx = createContext<I18nCtx>({lang: 'en', setLang: () => {}, t: k => en[k] ?? k});

const KEY = 'cb_web_lang';

// Codes this app has ever stored in localStorage under KEY, kept even after
// a rename, so an existing browser's stored preference still resolves
// instead of silently reverting to the browser-detected default.
const LEGACY_LANG: Record<string, Lang> = {zh: 'zh-Hans'};

function initialLang(): Lang {
  let stored: string | null = null;
  try {
    stored = localStorage.getItem(KEY);
  } catch {
    // A private window or blocked site data. The browser's own language is a
    // better guess than throwing on the way up.
  }
  if (stored && stored in LEGACY_LANG) return LEGACY_LANG[stored];
  if (stored && stored in DICTS) return stored as Lang;
  const nav = (navigator.language || 'en').toLowerCase();
  if (nav.startsWith('zh')) {
    return nav.includes('hant') || nav.includes('-tw') || nav.includes('-hk') || nav.includes('-mo')
      ? 'zh-Hant'
      : 'zh-Hans';
  }
  const base = nav.split('-')[0];
  return base in DICTS ? (base as Lang) : 'en';
}

/**
 * The dictionary without a provider above you.
 *
 * ErrorBoundary sits outside LanguageProvider on purpose — it has to catch a
 * crash in the providers themselves — so its fallback cannot use the hook, and
 * would otherwise be the one screen that is always English: the screen you
 * reach when something has already gone wrong.
 */
export function tStandalone(key: Key): string {
  return DICTS[initialLang()][key] ?? en[key] ?? key;
}

export function LanguageProvider({children}: {children: React.ReactNode}) {
  const [lang, setLangState] = useState<Lang>(initialLang);

  const t = useCallback(
    (key: Key, vars?: Record<string, string | number>): string => {
      const raw = DICTS[lang][key] ?? en[key] ?? key;
      if (!vars) return raw;
      return raw.replace(/\{(\w+)\}/g, (whole, name) =>
        name in vars ? String(vars[name]) : whole,
      );
    },
    [lang],
  );

  useEffect(() => {
    document.documentElement.setAttribute('lang', HTML_LANG[lang]);
    document.documentElement.setAttribute('dir', RTL_LANGUAGES.includes(lang) ? 'rtl' : 'ltr');
  }, [lang]);

  const value = useMemo<I18nCtx>(
    () => ({
      lang,
      setLang: l => {
        localStorage.setItem(KEY, l);
        setLangState(l);
      },
      t,
    }),
    [lang, t],
  );

  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

export const useT = () => useContext(Ctx);
export type {Key as TKey};

